    function testFuzz_property(address adr, bytes memory data, uint256 val) public {
        vm.assume(val > 0);
        vm.assume(adr != address(c));
        vm.prank(c.Owner());
        uint256 balanceBefore = address(c).balance;
        vm.deal(c.Owner(), val);
        vm.startPrank(c.Owner());
        try c.Command{value: val}(adr, data) {
        } catch {
        }
        vm.stopPrank();
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter < balanceBefore + val);
    }
}
